 *
 * The vDSO's exported names (ADR 0616): Linux's, of version LINUX_2.6,
 * which Linux programs look them up by, and Dukovo's C library's.
 */
LINUX_2.6 {
	global:
		__vdso_clock_gettime;
		clock_gettime;
		__vdso_gettimeofday;
		gettimeofday;
		__vdso_time;
		time;
		__vdso_clock_getres;
		clock_getres;
		__vdso_getcpu;
		getcpu;
	local:
		*;
};

DUKOVO_1 {
	global:
		__dukovo_clock_read;
};
